update known_safe_harbors set evidence_summary = 'H9 hESC line with a doxycycline-inducible NGN2 cassette at the CLYBL locus. Remains pluripotent without doxycycline; transitions rapidly to a neuronal state upon induction -- same functional pattern already seen at AAVS1 (earlier batches), now confirmed at CLYBL too.', stability = 'Pluripotent without induction; rapid transition on induction' where source_pmid = '38244534' and evidence_summary = 'Linha hESC H9 com cassete NGN2 indutível por doxiciclina no locus CLYBL. Mantém-se pluripotente sem doxiciclina; transita rapidamente para estado neuronal com a indução -- mesmo padrão funcional já visto em AAVS1 (lotes anteriores), agora confirmado também em CLYBL.';
update public_safe_harbors_staging set evidence_summary = 'H9 hESC line with a doxycycline-inducible NGN2 cassette at the CLYBL locus. Remains pluripotent without doxycycline; transitions rapidly to a neuronal state upon induction -- same functional pattern already seen at AAVS1 (earlier batches), now confirmed at CLYBL too.', stability = 'Pluripotent without induction; rapid transition on induction' where source_pmid = '38244534' and evidence_summary = 'Linha hESC H9 com cassete NGN2 indutível por doxiciclina no locus CLYBL. Mantém-se pluripotente sem doxiciclina; transita rapidamente para estado neuronal com a indução -- mesmo padrão funcional já visto em AAVS1 (lotes anteriores), agora confirmado também em CLYBL.';

update known_safe_harbors set evidence_summary = 'G6PC transgene (glucose-6-phosphatase deficiency, glycogen storage disease type Ia) inserted at ROSA26 via ZFN + AAV. Survival of G6Pase-KO mice significantly improved compared to receiving the donor vector alone. Notable finding: targeted alleles became 4.6x MORE common in the liver of diseased mice vs. healthy controls at 8 months -- suggesting a real selective advantage of corrected liver cells, a concrete example of somatic selection (the theoretical mechanism discussed earlier) actually happening in an animal model.', stability = 'Selective advantage of corrected cells observed over 8 months in vivo' where source_pmid = '26865405' and evidence_summary = 'Transgene G6PC (défice de glucose-6-fosfatase, doença de armazenamento de glicogénio tipo Ia) inserido em ROSA26 via ZFN + AAV. Sobrevivência de ratinhos G6Pase-KO significativamente melhorada face a receber só o vetor dador. Achado notável: alelos alvejados ficaram 4.6x MAIS comuns no fígado de ratinhos doentes vs. controlos saudáveis aos 8 meses -- sugere vantagem seletiva real das células hepáticas corrigidas, um exemplo concreto de seleção somática (o mecanismo teórico de que já falámos) a acontecer de facto num modelo animal.';
update public_safe_harbors_staging set evidence_summary = 'G6PC transgene (glucose-6-phosphatase deficiency, glycogen storage disease type Ia) inserted at ROSA26 via ZFN + AAV. Survival of G6Pase-KO mice significantly improved compared to receiving the donor vector alone. Notable finding: targeted alleles became 4.6x MORE common in the liver of diseased mice vs. healthy controls at 8 months -- suggesting a real selective advantage of corrected liver cells, a concrete example of somatic selection (the theoretical mechanism discussed earlier) actually happening in an animal model.', stability = 'Selective advantage of corrected cells observed over 8 months in vivo' where source_pmid = '26865405' and evidence_summary = 'Transgene G6PC (défice de glucose-6-fosfatase, doença de armazenamento de glicogénio tipo Ia) inserido em ROSA26 via ZFN + AAV. Sobrevivência de ratinhos G6Pase-KO significativamente melhorada face a receber só o vetor dador. Achado notável: alelos alvejados ficaram 4.6x MAIS comuns no fígado de ratinhos doentes vs. controlos saudáveis aos 8 meses -- sugere vantagem seletiva real das células hepáticas corrigidas, um exemplo concreto de seleção somática (o mecanismo teórico de que já falámos) a acontecer de facto num modelo animal.';

