update known_safe_harbors set locus_name = 'EPV loci (endogenous parvoviral elements) -- catalog, individual names to be confirmed', evidence_summary = 'Original approach: mapped 102 EPV loci (evolutionarily conserved endogenous parvoviral elements) in the human genome, 17 experimentally evaluated as safe-harbor candidates in CD34+ HSPCs. At least 6 tolerant to transgene insertion with low transcriptome disruption; 3 showed myeloid-lineage-specific regulation. Individual locus names/coordinates were not in the abstract -- candidate for full-text mining if exact names are wanted.', stability = 'At least 6/17 tolerant to insertion with low disruption' where source_pmid = '41438051' and evidence_summary = 'Abordagem original: mapeados 102 loci EPV (elementos parvovirais endógenos conservados evolutivamente) no genoma humano, 17 avaliados experimentalmente como candidatos a safe harbor em HSPCs CD34+. Pelo menos 6 tolerantes a inserção de transgene com baixa perturbação do transcriptoma; 3 mostraram regulação específica do ramo mieloide. Nomes/coordenadas individuais dos loci não estavam no abstract -- candidato a mineração de texto completo se quiseres os nomes exatos.';
update public_safe_harbors_staging set locus_name = 'EPV loci (endogenous parvoviral elements) -- catalog, individual names to be confirmed', evidence_summary = 'Original approach: mapped 102 EPV loci (evolutionarily conserved endogenous parvoviral elements) in the human genome, 17 experimentally evaluated as safe-harbor candidates in CD34+ HSPCs. At least 6 tolerant to transgene insertion with low transcriptome disruption; 3 showed myeloid-lineage-specific regulation. Individual locus names/coordinates were not in the abstract -- candidate for full-text mining if exact names are wanted.', stability = 'At least 6/17 tolerant to insertion with low disruption' where source_pmid = '41438051' and evidence_summary = 'Abordagem original: mapeados 102 loci EPV (elementos parvovirais endógenos conservados evolutivamente) no genoma humano, 17 avaliados experimentalmente como candidatos a safe harbor em HSPCs CD34+. Pelo menos 6 tolerantes a inserção de transgene com baixa perturbação do transcriptoma; 3 mostraram regulação específica do ramo mieloide. Nomes/coordenadas individuais dos loci não estavam no abstract -- candidato a mineração de texto completo se quiseres os nomes exatos.';

