update known_safe_harbors set evidence_summary = 'Direct CCR5 vs. AAVS1 comparison in human CD34+ HSPCs (ZFN mRNA + AAV6 donor): integration frequencies of 26% (mobilized peripheral blood) and 43% (fetal liver) at AAVS1, higher than those obtained at CCR5 in the same study (see paired CCR5 record). Modification confirmed in the rare CD34+CD133+CD90+ subpopulation (long-term hematopoietic stem cells), with long-term engraftment in immunodeficient mice.', stability = 'Long-term engraftment confirmed in immunodeficient mice' where source_pmid = '26551060' and evidence_summary = 'Comparação direta CCR5 vs. AAVS1 em HSPCs CD34+ humanas (ZFN mRNA + dador AAV6): frequências de integração de 26% (sangue periférico mobilizado) e 43% (fígado fetal) em AAVS1, superiores às obtidas em CCR5 no mesmo estudo (ver registo CCR5 associado). Confirmou-se modificação da subpopulação rara CD34+CD133+CD90+ (estaminais hematopoiéticas de longo prazo), com enxerto de longo prazo em ratinhos imunodeficientes.';
update public_safe_harbors_staging set evidence_summary = 'Direct CCR5 vs. AAVS1 comparison in human CD34+ HSPCs (ZFN mRNA + AAV6 donor): integration frequencies of 26% (mobilized peripheral blood) and 43% (fetal liver) at AAVS1, higher than those obtained at CCR5 in the same study (see paired CCR5 record). Modification confirmed in the rare CD34+CD133+CD90+ subpopulation (long-term hematopoietic stem cells), with long-term engraftment in immunodeficient mice.', stability = 'Long-term engraftment confirmed in immunodeficient mice' where source_pmid = '26551060' and evidence_summary = 'Comparação direta CCR5 vs. AAVS1 em HSPCs CD34+ humanas (ZFN mRNA + dador AAV6): frequências de integração de 26% (sangue periférico mobilizado) e 43% (fígado fetal) em AAVS1, superiores às obtidas em CCR5 no mesmo estudo (ver registo CCR5 associado). Confirmou-se modificação da subpopulação rara CD34+CD133+CD90+ (estaminais hematopoiéticas de longo prazo), com enxerto de longo prazo em ratinhos imunodeficientes.';

update known_safe_harbors set evidence_summary = 'Same study: integration frequencies at CCR5 of 17% (mobilized peripheral blood) and 19% (fetal liver) -- lower than those obtained at AAVS1 in the same study, but still effective for modifying long-term hematopoietic stem cells (CD34+CD133+CD90+) with confirmed engraftment.', stability = 'Long-term engraftment confirmed, at lower frequency than AAVS1' where source_pmid = '26551060' and evidence_summary = 'Mesmo estudo: frequências de integração em CCR5 de 17% (sangue periférico mobilizado) e 19% (fígado fetal) -- inferiores às obtidas em AAVS1 no mesmo estudo, mas ainda assim eficazes para modificar estaminais hematopoiéticas de longo prazo (CD34+CD133+CD90+) com enxerto confirmado.';
update public_safe_harbors_staging set evidence_summary = 'Same study: integration frequencies at CCR5 of 17% (mobilized peripheral blood) and 19% (fetal liver) -- lower than those obtained at AAVS1 in the same study, but still effective for modifying long-term hematopoietic stem cells (CD34+CD133+CD90+) with confirmed engraftment.', stability = 'Long-term engraftment confirmed, at lower frequency than AAVS1' where source_pmid = '26551060' and evidence_summary = 'Mesmo estudo: frequências de integração em CCR5 de 17% (sangue periférico mobilizado) e 19% (fígado fetal) -- inferiores às obtidas em AAVS1 no mesmo estudo, mas ainda assim eficazes para modificar estaminais hematopoiéticas de longo prazo (CD34+CD133+CD90+) com enxerto confirmado.';

update known_safe_harbors set locus_name = 'Random integration (lentivirus) -- safety context', evidence_summary = 'Analysis of common integration sites (CIS) in a real adrenoleukodystrophy clinical trial with a lentiviral vector: observed CIS cluster in broad (megabase-scale) chromosomal regions of high lentiviral integration density -- a benign integration bias, not oncogenic selection. Contrasts with CIS from gammaretroviral vectors in trials that caused cancer, which always target a single gene in narrow genomic intervals. Relatively good news specifically for lentivirus, but still not a named safe harbor.', stability = 'Benign integration bias, not oncogenic selection, in a real clinical trial' where source_pmid = '21403130' and evidence_summary = 'Análise de sítios de integração comuns (CIS) num ensaio clínico real de adrenoleucodistrofia com vetor lentiviral: os CIS observados agrupam-se em regiões cromossómicas largas (megabases) de alta densidade de integração lentiviral -- um viés de integração benigno, não seleção oncogénica. Contrasta com CIS de vetores gama-retrovirais em ensaios que causaram cancro, que visam sempre um único gene em intervalos genómicos estreitos. Boa notícia relativa para lentivírus especificamente, mas continua a não ser um safe harbor nomeado.';
update public_safe_harbors_staging set locus_name = 'Random integration (lentivirus) -- safety context', evidence_summary = 'Analysis of common integration sites (CIS) in a real adrenoleukodystrophy clinical trial with a lentiviral vector: observed CIS cluster in broad (megabase-scale) chromosomal regions of high lentiviral integration density -- a benign integration bias, not oncogenic selection. Contrasts with CIS from gammaretroviral vectors in trials that caused cancer, which always target a single gene in narrow genomic intervals. Relatively good news specifically for lentivirus, but still not a named safe harbor.', stability = 'Benign integration bias, not oncogenic selection, in a real clinical trial' where source_pmid = '21403130' and evidence_summary = 'Análise de sítios de integração comuns (CIS) num ensaio clínico real de adrenoleucodistrofia com vetor lentiviral: os CIS observados agrupam-se em regiões cromossómicas largas (megabases) de alta densidade de integração lentiviral -- um viés de integração benigno, não seleção oncogénica. Contrasta com CIS de vetores gama-retrovirais em ensaios que causaram cancro, que visam sempre um único gene em intervalos genómicos estreitos. Boa notícia relativa para lentivírus especificamente, mas continua a não ser um safe harbor nomeado.';

-- ===== batch 16 =====
update known_safe_harbors set evidence_summary = 'Nanobody-based (not conventional antibody) anti-CD105 CAR-T inserted at AAVS1 -- activation, proliferation, pro-inflammatory cytokine production, and specific killing of CD105+ target cells in vitro. In vivo, significantly inhibited implanted tumor growth and prolonged survival in NOD/SCID mice -- a rare solid-tumor data point, not just hematologic malignancy.', stability = 'Prolonged survival and tumor growth inhibition in vivo' where source_pmid = '33627635' and evidence_summary = 'CAR-T baseado em nanobody anti-CD105 (não anticorpo convencional) inserido em AAVS1 -- ativação, proliferação, produção de citocinas pró-inflamatórias e morte específica de células-alvo CD105+ in vitro. In vivo, inibiu significativamente crescimento de tumores implantados e prolongou sobrevivência em ratinhos NOD/SCID -- caso raro de dado em tumor sólido, não só malignidade hematológica.';
update public_safe_harbors_staging set evidence_summary = 'Nanobody-based (not conventional antibody) anti-CD105 CAR-T inserted at AAVS1 -- activation, proliferation, pro-inflammatory cytokine production, and specific killing of CD105+ target cells in vitro. In vivo, significantly inhibited implanted tumor growth and prolonged survival in NOD/SCID mice -- a rare solid-tumor data point, not just hematologic malignancy.', stability = 'Prolonged survival and tumor growth inhibition in vivo' where source_pmid = '33627635' and evidence_summary = 'CAR-T baseado em nanobody anti-CD105 (não anticorpo convencional) inserido em AAVS1 -- ativação, proliferação, produção de citocinas pró-inflamatórias e morte específica de células-alvo CD105+ in vitro. In vivo, inibiu significativamente crescimento de tumores implantados e prolongou sobrevivência em ratinhos NOD/SCID -- caso raro de dado em tumor sólido, não só malignidade hematológica.';

update known_safe_harbors set evidence_summary = 'A specific delivery method tested (dCas9-piggyBac transposase fusion with dual sgRNAs) for targeted integration at ROSA26 had very low efficiency: only 0.32% of cells. Not necessarily a locus failure, more a limitation of the delivery method tested -- but a real low-efficiency data point worth recording.', stability = 'Not a stability finding -- low delivery efficiency (0.32%) with this specific method' where source_pmid = '33496003' and evidence_summary = 'Método específico testado (fusão dCas9-transposase piggyBac com sgRNAs duplos) para integração dirigida em ROSA26 teve eficiência muito baixa: apenas 0.32% das células. Não é necessariamente falha do locus, é limitação do método de entrega testado -- mas é um dado real de baixa eficiência a registar.';
update public_safe_harbors_staging set evidence_summary = 'A specific delivery method tested (dCas9-piggyBac transposase fusion with dual sgRNAs) for targeted integration at ROSA26 had very low efficiency: only 0.32% of cells. Not necessarily a locus failure, more a limitation of the delivery method tested -- but a real low-efficiency data point worth recording.', stability = 'Not a stability finding -- low delivery efficiency (0.32%) with this specific method' where source_pmid = '33496003' and evidence_summary = 'Método específico testado (fusão dCas9-transposase piggyBac com sgRNAs duplos) para integração dirigida em ROSA26 teve eficiência muito baixa: apenas 0.32% das células. Não é necessariamente falha do locus, é limitação do método de entrega testado -- mas é um dado real de baixa eficiência a registar.';

update known_safe_harbors set locus_name = '(general calibration note, not a specific locus)', evidence_summary = 'Relevant citation from the very group that defined genomic safe-harbor criteria (Papapetrou and colleagues), reviewing their own criteria: "currently, there are no fully validated genomic safe harbors in the human genome". Worth using as a calibration -- even AAVS1/ROSA26/H11, despite being widely used, do not meet all the rigorous, fully validated criteria according to the definition''s own authors.', stability = 'Calibration note -- no locus is fully validated by the strictest criteria' where source_pmid = '26867951' and evidence_summary = 'Citação relevante do próprio grupo que definiu os critérios de safe harbor genómico (Papapetrou e colegas), a rever os seus próprios critérios: "atualmente, não existem safe harbors genómicos totalmente validados no genoma humano". Vale como calibração -- mesmo AAVS1/ROSA26/H11, apesar de amplamente usados, não cumprem todos os critérios rigorosos com validação completa segundo os próprios autores da definição.';
update public_safe_harbors_staging set locus_name = '(general calibration note, not a specific locus)', evidence_summary = 'Relevant citation from the very group that defined genomic safe-harbor criteria (Papapetrou and colleagues), reviewing their own criteria: "currently, there are no fully validated genomic safe harbors in the human genome". Worth using as a calibration -- even AAVS1/ROSA26/H11, despite being widely used, do not meet all the rigorous, fully validated criteria according to the definition''s own authors.', stability = 'Calibration note -- no locus is fully validated by the strictest criteria' where source_pmid = '26867951' and evidence_summary = 'Citação relevante do próprio grupo que definiu os critérios de safe harbor genómico (Papapetrou e colegas), a rever os seus próprios critérios: "atualmente, não existem safe harbors genómicos totalmente validados no genoma humano". Vale como calibração -- mesmo AAVS1/ROSA26/H11, apesar de amplamente usados, não cumprem todos os critérios rigorosos com validação completa segundo os próprios autores da definição.';

-- ===== batch 17 =====
update known_safe_harbors set evidence_summary = 'Structural (X-ray) detail of how the AAV Rep68 protein recognizes and assembles at the AAVS1 site: multiple GCTC repeats recognized by a glycine-rich loop and a helix interacting with the minor groove; the full heptameric complex requires a minimum of two direct repeats to form and melt the DNA. Explains at the molecular level the specificity of integration at this locus.', stability = 'Mechanistic/structural explanation (not a duration measurement)' where source_pmid = '26370092' and evidence_summary = 'Detalhe estrutural (raio-X) de como a proteína Rep68 do AAV reconhece e monta-se no sítio AAVS1: repetições GCTC múltiplas reconhecidas por um loop rico em glicina e uma hélice que interage com o sulco menor; complexo heptamérico completo requer no mínimo duas repetições diretas para se formar e derreter o DNA. Explica ao nível molecular a especificidade da integração neste locus.';
update public_safe_harbors_staging set evidence_summary = 'Structural (X-ray) detail of how the AAV Rep68 protein recognizes and assembles at the AAVS1 site: multiple GCTC repeats recognized by a glycine-rich loop and a helix interacting with the minor groove; the full heptameric complex requires a minimum of two direct repeats to form and melt the DNA. Explains at the molecular level the specificity of integration at this locus.', stability = 'Mechanistic/structural explanation (not a duration measurement)' where source_pmid = '26370092' and evidence_summary = 'Detalhe estrutural (raio-X) de como a proteína Rep68 do AAV reconhece e monta-se no sítio AAVS1: repetições GCTC múltiplas reconhecidas por um loop rico em glicina e uma hélice que interage com o sulco menor; complexo heptamérico completo requer no mínimo duas repetições diretas para se formar e derreter o DNA. Explica ao nível molecular a especificidade da integração neste locus.';

update known_safe_harbors set evidence_summary = 'Reinforces the biological caveat already on record: CLYBL encodes a real malate/beta-methylmalate synthase enzyme, linked to the mitochondrial vitamin B12 pathway. About 5% of all humans naturally carry a premature-stop polymorphism in CLYBL (complete loss of protein expression) associated with reduced circulating B12 levels -- a reassuring precedent: CLYBL loss-of-function already exists naturally in a substantial fraction of the human population with an apparently mild effect.', stability = 'Natural precedent: CLYBL loss-of-function tolerated in ~5% of the population' where source_pmid = '24334609' and evidence_summary = 'Reforço à ressalva biológica já registada: CLYBL codifica uma malato/beta-metilmalato sintase real, ligada à via mitocondrial da vitamina B12. Cerca de 5% de todos os humanos têm naturalmente um polimorfismo de paragem prematura no CLYBL (perda completa de expressão da proteína) associado a níveis reduzidos de B12 circulante -- é um precedente tranquilizador: perda de função de CLYBL já existe naturalmente numa fração substancial da população humana com efeito aparentemente ligeiro.';
update public_safe_harbors_staging set evidence_summary = 'Reinforces the biological caveat already on record: CLYBL encodes a real malate/beta-methylmalate synthase enzyme, linked to the mitochondrial vitamin B12 pathway. About 5% of all humans naturally carry a premature-stop polymorphism in CLYBL (complete loss of protein expression) associated with reduced circulating B12 levels -- a reassuring precedent: CLYBL loss-of-function already exists naturally in a substantial fraction of the human population with an apparently mild effect.', stability = 'Natural precedent: CLYBL loss-of-function tolerated in ~5% of the population' where source_pmid = '24334609' and evidence_summary = 'Reforço à ressalva biológica já registada: CLYBL codifica uma malato/beta-metilmalato sintase real, ligada à via mitocondrial da vitamina B12. Cerca de 5% de todos os humanos têm naturalmente um polimorfismo de paragem prematura no CLYBL (perda completa de expressão da proteína) associado a níveis reduzidos de B12 circulante -- é um precedente tranquilizador: perda de função de CLYBL já existe naturalmente numa fração substancial da população humana com efeito aparentemente ligeiro.';

update known_safe_harbors set evidence_summary = 'Important mechanistic nuance (2004): the NATURAL integration of wild-type AAV at AAVS1 (Rep-mediated, not CRISPR) is actually inefficient in any context -- the persistence of AAV delivery vectors in tissues is largely due to episomal genomes, not true chromosomal integration. This does not contradict data on CRISPR/nuclease-targeted insertion at AAVS1 (a different mechanism, via HDR after a directed cut), but is a reminder that the natural biology of AAV itself is not the same process as modern gene editing at this locus.', stability = 'Mechanistic caveat (not a duration measurement)' where source_pmid = '15568995' and evidence_summary = 'Nuance mecanística importante (2004): a integração NATURAL do AAV selvagem em AAVS1 (mediada por Rep, não CRISPR) é na realidade ineficiente em qualquer contexto -- a persistência de vetores de entrega por AAV em tecidos deve-se largamente a genomas epissomais, não a integração cromossómica real. Isto não contradiz os dados de inserção alvejada por CRISPR/nuclease em AAVS1 (mecanismo diferente, via HDR após corte dirigido), mas é um lembrete de que a biologia natural do AAV em si não é o mesmo processo que a edição genética moderna neste locus.';
update public_safe_harbors_staging set evidence_summary = 'Important mechanistic nuance (2004): the NATURAL integration of wild-type AAV at AAVS1 (Rep-mediated, not CRISPR) is actually inefficient in any context -- the persistence of AAV delivery vectors in tissues is largely due to episomal genomes, not true chromosomal integration. This does not contradict data on CRISPR/nuclease-targeted insertion at AAVS1 (a different mechanism, via HDR after a directed cut), but is a reminder that the natural biology of AAV itself is not the same process as modern gene editing at this locus.', stability = 'Mechanistic caveat (not a duration measurement)' where source_pmid = '15568995' and evidence_summary = 'Nuance mecanística importante (2004): a integração NATURAL do AAV selvagem em AAVS1 (mediada por Rep, não CRISPR) é na realidade ineficiente em qualquer contexto -- a persistência de vetores de entrega por AAV em tecidos deve-se largamente a genomas epissomais, não a integração cromossómica real. Isto não contradiz os dados de inserção alvejada por CRISPR/nuclease em AAVS1 (mecanismo diferente, via HDR após corte dirigido), mas é um lembrete de que a biologia natural do AAV em si não é o mesmo processo que a edição genética moderna neste locus.';

