update known_safe_harbors set evidence_summary = 'Same study: efficient targeted transgene insertion also confirmed at AAVS1 in mouse and human NSCs -- both loci used side by side as reference "safe harbour loci" in the same protocol.', stability = 'Efficient targeted insertion in NSCs (duration not further quantified)' where source_pmid = '28096221' and evidence_summary = 'Mesmo estudo: inserção alvejada eficiente de transgene também confirmada em AAVS1 em NSCs de ratinho e humanas -- ambos os loci usados lado a lado como "safe harbour loci" de referência no mesmo protocolo.';
