update known_safe_harbors set locus_name = 'A2UCOE element (anti-silencing tool, not a locus)', evidence_summary = 'Not a locus, it is a regulatory element that attaches to ANY construct to protect it from silencing: A2UCOE (derived from the housekeeping HNRPA2B1-CBX3 locus) confers resistance to DNA-methylation-mediated silencing of lentiviral vectors. SFFV/EF1a promoters alone silenced within 16 days; linked upstream of A2UCOE, they remained completely stable, with near-total resistance to CpG methylation -- also confirmed in vivo in engrafted hematopoietic cells. A complementary tool to whichever safe-harbor locus is chosen, not a substitute for one.', stability = 'Complete stability vs. silencing within 16 days without A2UCOE' where source_pmid = '20588258' and evidence_summary = 'Não é um locus, é um elemento regulador que se liga a QUALQUER construção para a proteger de silenciamento: A2UCOE (derivado do locus housekeeping HNRPA2B1-CBX3) confere resistência a silenciamento mediado por metilação de DNA em vetores lentivirais. Promotores SFFV/EF1a sozinhos silenciaram em 16 dias; ligados a montante do A2UCOE, mantiveram-se completamente estáveis, com resistência quase total à metilação de CpG -- confirmado também in vivo em células hematopoiéticas enxertadas. Ferramenta complementar a qualquer locus safe harbor escolhido, não um substituto.';
update public_safe_harbors_staging set locus_name = 'A2UCOE element (anti-silencing tool, not a locus)', evidence_summary = 'Not a locus, it is a regulatory element that attaches to ANY construct to protect it from silencing: A2UCOE (derived from the housekeeping HNRPA2B1-CBX3 locus) confers resistance to DNA-methylation-mediated silencing of lentiviral vectors. SFFV/EF1a promoters alone silenced within 16 days; linked upstream of A2UCOE, they remained completely stable, with near-total resistance to CpG methylation -- also confirmed in vivo in engrafted hematopoietic cells. A complementary tool to whichever safe-harbor locus is chosen, not a substitute for one.', stability = 'Complete stability vs. silencing within 16 days without A2UCOE' where source_pmid = '20588258' and evidence_summary = 'Não é um locus, é um elemento regulador que se liga a QUALQUER construção para a proteger de silenciamento: A2UCOE (derivado do locus housekeeping HNRPA2B1-CBX3) confere resistência a silenciamento mediado por metilação de DNA em vetores lentivirais. Promotores SFFV/EF1a sozinhos silenciaram em 16 dias; ligados a montante do A2UCOE, mantiveram-se completamente estáveis, com resistência quase total à metilação de CpG -- confirmado também in vivo em células hematopoiéticas enxertadas. Ferramenta complementar a qualquer locus safe harbor escolhido, não um substituto.';

update known_safe_harbors set evidence_summary = 'Historical founding paper (1991): first mapping of AAV integration to human chromosome 19, distal q arm, confirmed by in situ hybridization as q13.4-ter. Integration breakpoints occur within a cellular region of only 100 base pairs -- the original discovery that gave rise to the name "AAVS1".', stability = 'Historical/founding structural finding (not a duration measurement)' where source_pmid = '1657596' and evidence_summary = 'Paper fundador histórico (1991): primeiro mapeamento da integração do AAV ao cromossoma 19 humano, região distal do braço q, confirmado por hibridação in situ como q13.4-ter. Pontos de quebra de integração ocorrem numa região celular de apenas 100 pares de bases -- a descoberta original que deu origem ao nome "AAVS1".';
update public_safe_harbors_staging set evidence_summary = 'Historical founding paper (1991): first mapping of AAV integration to human chromosome 19, distal q arm, confirmed by in situ hybridization as q13.4-ter. Integration breakpoints occur within a cellular region of only 100 base pairs -- the original discovery that gave rise to the name "AAVS1".', stability = 'Historical/founding structural finding (not a duration measurement)' where source_pmid = '1657596' and evidence_summary = 'Paper fundador histórico (1991): primeiro mapeamento da integração do AAV ao cromossoma 19 humano, região distal do braço q, confirmado por hibridação in situ como q13.4-ter. Pontos de quebra de integração ocorrem numa região celular de apenas 100 pares de bases -- a descoberta original que deu origem ao nome "AAVS1".';

